functions:
/*  FUNCTION NAME:  SensitivityGridλ
    DESCRIPTION:*//**Two-way sensitivity grid: a calculation's result for each pair of row and column values, recalculated with the workbook and without a Data Table*/
SensitivityGridλ = LAMBDA(
//  Parameter Declaration
    [Calculation],
    [RowValues],
    [ColumnValues],
    LET(
    //  Help
        Help,           TRIM(TEXTSPLIT(
                            "FUNCTION:      →SensitivityGridλ(Calculation, RowValues, ColumnValues)¶" &
                            "DESCRIPTION:   →Two-way sensitivity grid: a result for each pair of row and column values.¶NOTES!         →Two-way sensitivity grid: Calculation's result for each value in RowValues¶               →(down) paired with each value in ColumnValues (across), one row for each¶               →row value and one column for each column value, in their order. Place the¶               →row values to the left of the grid and the column values above it. It¶               →recalculates with the workbook like any formula, without a What-If Data¶               →Table. Calculation is a LAMBDA of 2 parameters, the row value then the¶               →column value, returning one value. An error in a result shows in its cell;¶               →a LAMBDA with the wrong number of parameters gives #VALUE! in every cell.¶" &
                            "WEBPAGE:       →https://github.com/ryanduguid/Ozzit/blob/main/docs/valuation-and-sensitivity.md¶" &
                            "VERSION:       →24 Nov 2026¶" &
                            "PARAMETERS:    →¶" &
                            "Calculation    →(Required) A LAMBDA of a row value and a column value that returns one value.¶" &
                            "RowValues      →(Required) One column of values to try down the grid, at most 1,000.¶" &
                            "ColumnValues   →(Required) One row of values to try across the grid, at most 1,000.¶" &
                            "EXAMPLES:      →¶" &
                            "→Formula (oz is assumed to be the module's name)¶" &
                            "→=oz.SensitivityGridλ(LAMBDA(Rate, Growth, 100 / (Rate - Growth)), {0.08;0.1}, {0.02,0.03})¶" &
                            "→Result¶" &
                            "→1666.6667, 2000¶" &
                            "→     1250, 1428.5714",
                            "→", "¶"
                        )),
    //  Check inputs - Omitted required arguments
        Help?,          OR( ISOMITTED( Calculation), ISOMITTED( RowValues), ISOMITTED( ColumnValues)),
    //  RowValues one column and ColumnValues one row, each at most 1,000 values
        Down,           IFERROR( ROWS( RowValues), 1),
        Across,         IFERROR( COLUMNS( ColumnValues), 1),
        ValidShape?,    AND( IFERROR( COLUMNS( RowValues) = 1, ISERROR( RowValues)), Down <= 1000,
                            IFERROR( ROWS( ColumnValues) = 1, ISERROR( ColumnValues)), Across <= 1000),
        ShapeMessage,   "SensitivityGridλ needs RowValues as one column and ColumnValues as one row, each of at most 1,000 values.",
    //  Calculation is a LAMBDA (TYPE 128) or an error, and returns one value for the first pair;
    //  an error result passes so it shows
        Function?,      OR( TYPE( Calculation) = 16, TYPE( Calculation) = 128),
        First,          Calculation( INDEX( RowValues, 1, 1), INDEX( ColumnValues, 1, 1)),
        OneValue?,      IFERROR( ROWS( First) * COLUMNS( First) = 1, ISERROR( First)),
        CalculationMessage, "SensitivityGridλ needs Calculation to be a LAMBDA of a row value and a column value that returns one value.",
    //  Procedure - the calculation for each row value and column value
        Result,         MAKEARRAY( Down, Across, LAMBDA( i, j,
                            Calculation( INDEX( RowValues, i, 1), INDEX( ColumnValues, 1, j))
                        )),
    //  Return Result, Help, or the message
        Return,         IF( Help?, 2, IF( NOT( ValidShape?), 3, IF( NOT( AND( Function?, OneValue?)), 4, 1))),
        CHOOSE( Return, Result, Help, ShapeMessage, CalculationMessage)
    )
);
